// ─── File: AnonymousDemo.java ───
// Single runnable file with multiple top-level package-private classes.
// In a real project each class would live in its own file.
package com.bank.anon;

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class AnonymousDemo {
    private static final Logger log = Logger.getLogger(AnonymousDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        TransferService service = new TransferService();

        // A multi-method listener MUST be an anonymous class — a lambda cannot
        // implement an interface that has more than one abstract method.
        service.setListener(new TransferListener() {
            @Override public void onStart(String from, String to, BigDecimal amount) {
                log.info(() -> "LISTENER start: " + from + " -> " + to + " Rs." + amount);
            }
            @Override public void onComplete(String reference) {
                log.info(() -> "LISTENER complete: ref=" + reference);
            }
        });

        // A single-method callback as an ANONYMOUS class. Here `this` would
        // refer to this anonymous object, not AnonymousDemo.
        TransferCallback anonCallback = new TransferCallback() {
            @Override public void onResult(String reference, boolean success) {
                log.info(() -> "ANON callback ref=" + reference + " success=" + success);
            }
        };

        // The SAME callback as a LAMBDA — only works because TransferCallback
        // is a functional interface (exactly one abstract method).
        TransferCallback lambdaCallback =
            (reference, success) -> log.info(() -> "LAMBDA callback ref=" + reference + " success=" + success);

        BigDecimal rentAmount = new BigDecimal("50000");
        service.transfer(rajesh, priya, rentAmount, anonCallback);
        service.transfer(rajesh, priya, rentAmount, lambdaCallback);

        // Sorting with an ANONYMOUS Comparator (captures effectively-final list order).
        List<Trade> trades = new ArrayList<>(List.of(
            new Trade("TRD-1", new BigDecimal("2450")),
            new Trade("TRD-2", new BigDecimal("980")),
            new Trade("TRD-3", new BigDecimal("15000"))));

        trades.sort(new Comparator<Trade>() {
            @Override public int compare(Trade a, Trade b) {
                return a.getAmount().compareTo(b.getAmount());
            }
        });
        log.info(() -> "Sorted by ANON comparator: " + trades);

        // Same rule as a lambda — concise for a single-method functional interface.
        trades.sort((a, b) -> b.getAmount().compareTo(a.getAmount()));
        log.info(() -> "Sorted by LAMBDA comparator: " + trades);
    }
}

// ─── Would be in model/Account.java ───
class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId; this.holderName = holderName; this.balance = balance;
    }
    void debit(BigDecimal amount) {
        if (balance.compareTo(amount) < 0) throw new IllegalStateException("Insufficient funds");
        balance = balance.subtract(amount);
    }
    void credit(BigDecimal amount) { balance = balance.add(amount); }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
}

// ─── Would be in model/Trade.java ───
class Trade {
    private final String tradeId;
    private final BigDecimal amount;
    Trade(String tradeId, BigDecimal amount) { this.tradeId = tradeId; this.amount = amount; }
    BigDecimal getAmount() { return amount; }
    @Override public String toString() { return tradeId + "(Rs." + amount + ")"; }
}

// ─── Would be in callback/TransferCallback.java ───
// Functional interface: exactly one abstract method, so a lambda can implement it.
@FunctionalInterface
interface TransferCallback {
    void onResult(String reference, boolean success);
}

// ─── Would be in callback/TransferListener.java ───
// Multi-method interface: a lambda CANNOT implement this; use an anonymous class.
interface TransferListener {
    void onStart(String from, String to, BigDecimal amount);
    void onComplete(String reference);
}

// ─── Would be in service/TransferService.java ───
class TransferService {
    private static final Logger log = Logger.getLogger(TransferService.class.getName());
    private TransferListener listener;
    private int counter = 0;

    void setListener(TransferListener listener) { this.listener = listener; }

    void transfer(Account from, Account to, BigDecimal amount, TransferCallback callback) {
        String reference = "TXF-" + (++counter);
        if (listener != null) listener.onStart(from.getAccountId(), to.getAccountId(), amount);
        boolean success;
        try {
            from.debit(amount);
            to.credit(amount);
            success = true;
            log.info(() -> "Transfer " + amount + " from " + from.getAccountId()
                    + " to " + to.getAccountId() + " ref=" + reference);
        } catch (RuntimeException ex) {
            success = false;
            log.log(Level.SEVERE, "Transfer failed ref=" + reference, ex);
        }
        callback.onResult(reference, success);
        if (listener != null && success) listener.onComplete(reference);
    }
}

